insert into public.catalog_formats (
  code, format_type, series_id, repetitions_id, rest_id, interval_id,
  label, description, source_status, updated_at
)
select
  seed.code, seed.format_type, series.id, repetitions.id, rests.id, intervals.id,
  seed.label, seed.description, seed.source_status, seed.updated_at
from seed
join public.catalog_series series on series.code = seed.series_code
left join public.catalog_repetitions repetitions on repetitions.code = seed.repetitions_code
join public.catalog_rests rests on rests.code = seed.rest_code
left join public.catalog_intervals intervals on intervals.code = seed.interval_code
on conflict (code) do update set
  format_type = excluded.format_type,
  series_id = excluded.series_id,
  repetitions_id = excluded.repetitions_id,
  rest_id = excluded.rest_id,
  interval_id = excluded.interval_id,
  label = excluded.label,
  description = excluded.description,
  source_status = excluded.source_status,
  updated_at = excluded.updated_at;
-- Public evaluation export: private historical exercise/session rows omitted.


